import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createGate, QuotaExceededError } from '../src/index.js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

test('exports the documented surface', () => {
  const keys = Object.keys(await import('../src/index.js'));
  assert.deepEqual(keys, ['QUOTA_EXCEEDED', 'WAIT_EXPIRED', 'QuotaExceededError', 'createGate']);
});

test('stats echoes config and starts empty with README key order', () => {
  const gate = createGate({ limit: 3, windowMs: 1000 });
  assert.deepEqual(Object.keys(gate.stats()), [
    'limit',
    'windowMs',
    'inFlight',
    'waiting',
    'granted',
    'refused',
    'expired',
  ]);
  assert.deepEqual(gate.stats(), {
    limit: 3,
    windowMs: 1000,
    inFlight: 0,
    waiting: 0,
    granted: 0,
    refused: 0,
    expired: 0,
  });
});

test('admits within the window and refuses overflow with QUOTA_EXCEEDED', async () => {
  const gate = createGate({ limit: 2, windowMs: 60_000 });
  const a = await gate.acquire();
  const b = await gate.acquire(1);
  await assert.rejects(gate.acquire(), (err) => {
    assert.ok(err instanceof QuotaExceededError);
    assert.equal(err.code, 'QUOTA_EXCEEDED');
    return true;
  });
  assert.deepEqual(
    { ...gate.stats() },
    { limit: 2, windowMs: 60_000, inFlight: 2, waiting: 0, granted: 2, refused: 1, expired: 0 },
  );
  a.release();
  b.release();
  assert.equal(gate.stats().inFlight, 0);
  // Release does not refund the spent window quota.
  await assert.rejects(gate.acquire(), (err) => err.code === 'QUOTA_EXCEEDED');
  assert.equal(gate.stats().refused, 2);
});

test('release handle is idempotent and never changes stats twice', async () => {
  const gate = createGate({ limit: 1, windowMs: 60_000 });
  const handle = await gate.acquire();
  handle.release();
  handle.release();
  handle.release();
  assert.equal(gate.stats().inFlight, 0);
  assert.equal(gate.stats().granted, 1);
});

test('queue is FIFO: small requests never overtake earlier ones', async () => {
  const gate = createGate({ limit: 2, windowMs: 60_000 });
  await gate.acquire(2); // fills the window

  const order = [];
  const big = gate.acquire(2).then(
    () => order.push('big'),
    () => order.push('big-reject'),
  );
  const small = gate.acquire(1).then(
    () => order.push('small'),
    () => order.push('small-reject'),
  );
  await sleep(5);
  assert.equal(gate.stats().waiting, 3); // 2 + 1 queued units
  // Nothing is granted outside a page turn, even though a unit could fit.
  assert.equal(order.length, 0);
  await Promise.all([big, small]);
  assert.deepEqual(order, ['big', 'small']);
  assert.equal(gate.stats().granted, 4);
});

test('requests are all-or-nothing and a head that does not fit blocks the line', async () => {
  const gate = createGate({ limit: 5, windowMs: 40, maxWaitMs: 1000 });
  await gate.acquire(4);

  const head = gate.acquire(3); // needs a fresh window
  const tail = gate.acquire(2); // could share, but must wait behind head

  const [h, t] = await Promise.all([head, tail]);
  assert.equal(gate.stats().inFlight, 5);
  h.release();
  t.release();
});

test('page turn resets quota and ends outstanding occupancies', async () => {
  const gate = createGate({ limit: 2, windowMs: 40, maxWaitMs: 1000 });
  const hold = await gate.acquire(2);
  const queued = gate.acquire(2);

  await sleep(70); // page turns twice
  assert.equal(gate.stats().inFlight, 2); // queued one admitted, old one ended
  hold.release(); // late release is a no-op on stats
  assert.equal(gate.stats().inFlight, 2);
  const handle = await queued;
  handle.release();
  assert.equal(gate.stats().inFlight, 0);
});

test('waiting requests expire with WAIT_EXPIRED before a later page', async () => {
  const gate = createGate({ limit: 1, windowMs: 200, maxWaitMs: 30 });
  await gate.acquire(1);

  await assert.rejects(
    gate.acquire(1),
    (err) => err instanceof QuotaExceededError && err.code === 'WAIT_EXPIRED',
  );
  const s = gate.stats();
  assert.equal(s.expired, 1);
  assert.equal(s.waiting, 0);
  assert.equal(s.granted, 1);
  assert.equal(s.refused, 0);
});

test('expiry is judged before allocation on a page turn', async () => {
  // maxWaitMs expires just before the first rollover can admit.
  const gate = createGate({ limit: 1, windowMs: 60, maxWaitMs: 25 });
  await gate.acquire(1);
  await assert.rejects(gate.acquire(1), (err) => err.code === 'WAIT_EXPIRED');
  assert.equal(gate.stats().expired, 1);
});

test('a request expiring on the exact rollover tick counts as expired', async () => {
  const gate = createGate({ limit: 1, windowMs: 50, maxWaitMs: 50 });
  await gate.acquire(1);
  // Acquired immediately after gate creation: deadline ~= first rollover time.
  await assert.rejects(gate.acquire(1), (err) => err.code === 'WAIT_EXPIRED');
  assert.equal(gate.stats().expired, 1);
  assert.equal(gate.stats().granted, 1);
});

test('createGate validates types and ranges', () => {
  for (const bad of [undefined, null, '3', 1.5, NaN, true]) {
    assert.throws(() => createGate({ limit: bad, windowMs: 10 }), TypeError);
    assert.throws(() => createGate({ limit: 1, windowMs: bad }), TypeError);
    assert.throws(() => createGate({ limit: 1, windowMs: 10, maxWaitMs: bad }), TypeError);
  }
  assert.throws(() => createGate({ limit: 0, windowMs: 10 }), RangeError);
  assert.throws(() => createGate({ limit: -1, windowMs: 10 }), RangeError);
  assert.throws(() => createGate({ limit: 1, windowMs: 0 }), RangeError);
  assert.throws(() => createGate({ limit: 1, windowMs: -5 }), RangeError);
  assert.throws(() => createGate({ limit: 1, windowMs: 10, maxWaitMs: -1 }), RangeError);
});

test('acquire validates units types and ranges without counting quota stats', async () => {
  const gate = createGate({ limit: 2, windowMs: 60_000 });
  for (const bad of [null, '1', 1.2, NaN]) {
    assert.throws(() => gate.acquire(bad), TypeError);
  }
  assert.throws(() => gate.acquire(0), RangeError);
  assert.throws(() => gate.acquire(-1), RangeError);
  assert.throws(() => gate.acquire(3), RangeError);
  const s = gate.stats();
  assert.equal(s.granted + s.refused + s.expired, 0);
});

test('default units is 1 and default maxWaitMs refuses immediately', async () => {
  const gate = createGate({ limit: 1, windowMs: 60_000 });
  assert.doesNotReject(gate.acquire());
  await assert.rejects(gate.acquire(), (err) => err.code === 'QUOTA_EXCEEDED');
});

